 internal void Verify(string root){Reload();var original=owner.Configuration;try{string export=System.IO.Path.Combine(root,"Preview HUD.dat");System.IO.File.WriteAllBytes(export,HudExportHotbarVerification.Encode(HudExportHotbarVerification.Fixture()));byte[] source=System.IO.File.ReadAllBytes(export);PrepareHudExport(export);string prepared=owner.Configuration.SkillSlots.PreparedHudFile;if(!System.IO.File.Exists(prepared)||!System.IO.File.ReadAllBytes(export).SequenceEqual(source)||!nativeState.Text.Contains(owner.Language=="es"?"Guardar":"Save"))throw new Exception("Settings must create an original-preserving copy and require in-game Save");var span=owner.Configuration.Copy();span.Language="es";owner.ApplyConfiguration(span);Reload();scroll.ScrollToTop();SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-hud-import-es.png"));window.UpdateLayout();scroll.ScrollToVerticalOffset(hudGuide.TransformToAncestor(controls).Transform(new Point()).Y-52);SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-hud-guide-es.png"));span.Language="en";owner.ApplyConfiguration(span);Reload();scroll.ScrollToTop();SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-hud-import-en.png"));window.UpdateLayout();scroll.ScrollToVerticalOffset(hudGuide.TransformToAncestor(controls).Transform(new Point()).Y-52);SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-hud-guide-en.png"));PrepareHudExport(System.IO.Path.Combine(root,"missing-export.dat"));if(owner.Configuration.SkillSlots.PreparedHudFile!=prepared||!System.IO.File.ReadAllBytes(export).SequenceEqual(source))throw new Exception("A failed export preparation cannot lose a previously prepared path or change the source");hudMessage=null;owner.ApplyConfiguration(original);var cfg=original.Copy();cfg.SkillSlots.GroupMode=false;owner.ApplyConfiguration(cfg);Reload();
 var saved=owner.Configuration.SkillSlots.Copy();testButton.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));if(!owner.SkillSlots.Testing||UiLanguage.Text(Convert.ToString(testButton.Content),"en")!="Stop test")throw new Exception("One test button must start and change to Stop test");owner.SkillSlots.Maintain(DpsHistory.UtcNow()+40);if(!owner.SkillSlots.Testing||!owner.SkillSlots.Current.Select(s=>s.Index).SequenceEqual(choices.Select(s=>s.Index)))throw new Exception("Loop continues past20seconds and uses detected slot identities");if(!SkillSlotsOptions.Same(saved,owner.Configuration.SkillSlots))throw new Exception("Test must preserve hotbar activation, labels and layout");testButton.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));if(owner.SkillSlots.Testing||UiLanguage.Text(Convert.ToString(testButton.Content),"en")!="Test hotbar")throw new Exception("The same button must stop and regain its start label");
 cfg=owner.Configuration;cfg.SkillSlots.Enabled=false;owner.ApplyConfiguration(cfg);Reload();testButton.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));if(!owner.SkillSlots.Testing||owner.Configuration.SkillSlots.Enabled)throw new Exception("Testing a disabled module must not permanently enable it");testButton.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));if(owner.SkillSlots.Testing||owner.Configuration.SkillSlots.Enabled)throw new Exception("Stopping restores the disabled state");cfg.SkillSlots=saved;owner.ApplyConfiguration(cfg);Reload();int count=choices.Count;if(selected.Items.Count!=count||count==0)throw new Exception("Only actual detected/saved slots belong in the selector");int raw=choices[count-1].Index;selected.SelectedIndex=count-1;if(selectedIndex!=raw)throw new Exception("Consecutive choice must edit its own internal identity");hideSlot.IsChecked=true;hideSlot.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));owner.SkillSlots.Maintain();if(owner.Configuration.SkillSlots.Placements.First(p=>p.Slot==raw).Visible||selected.Items.Count!=count)throw new Exception("Hidden slot must remain selectable for restoration");hideSlot.IsChecked=false;hideSlot.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));if(!owner.Configuration.SkillSlots.Placements.First(p=>p.Slot==raw).Visible)throw new Exception("Individual toggle must restore the same slot");SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-skill-slots.png"));window.UpdateLayout();scroll.ScrollToVerticalOffset(testButton.TransformToAncestor(controls).Transform(new Point()).Y-160);SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-hotbar-single-test.png"));scroll.ScrollToVerticalOffset(individual.TransformToAncestor(controls).Transform(new Point()).Y-10);SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-skill-slots-individual.png"));}finally{owner.ApplyConfiguration(original);Reload();}}
